<!--vbase-->
<template>
  <div class="container text-color-white settings-container bg-wrapper">
    <div class="q-py-md">
      <q-input
        outlined
        dense
        clearable
        debounce="300"
        color="primary"
        class="q-mb-md"
        :model-value="searchQuery"
        @update:model-value="onSearchFilter"
        :placeholder="$t('search_edi_formats')"
      >
        <template v-slot:prepend>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-list bordered class="rounded-borders">
        <!-- Empty state for search -->
        <div
          v-if="searchQuery && Object.keys(filteredEDocData).length === 0"
          class="q-pa-xl text-center text-grey-6"
        >
          <q-icon name="search_off" size="48px" class="q-mb-md" />
          <div class="text-h6">{{ $t('no_results_found') }}</div>
          <div class="text-body2">
            {{ $t('no_edi_formats_match') }} "{{ searchQuery }}"
          </div>
        </div>
        <template
          v-for="([key, item], index) in Object.entries(filteredEDocData)"
          :key="index"
        >
          <div v-if="item && item.length" :data-edoc-format="key">
            <q-expansion-item
              :default-opened="
                $route.query.tab?.toString().toUpperCase() === key
              "
            >
              <template v-slot:header>
                <q-item-section avatar>
                  <q-avatar
                    icon="description"
                    color="primary"
                    text-color="white"
                  />
                </q-item-section>

                <q-item-section>
                  <div class="row items-center q-gutter-sm">
                    <span>{{ getCountryFlag(key) }} {{ key }}</span>
                    <q-badge
                      :label="item.length"
                      color="primary"
                      text-color="white"
                      size="sm"
                    />
                    <q-tooltip>
                      {{ getFormatTooltip(key) }}
                    </q-tooltip>
                  </div>
                </q-item-section>
              </template>

              <q-card>
                <div class="container">
                  <div class="full-width q-pa-md">
                    <div class="row q-mb-md" v-if="is_admin == true">
                      <q-space />
                      <f-btn
                        v-if="hasCustomAttributes(item)"
                        flat
                        color="warning"
                        icon="restart_alt"
                        :label="$t('reset_all_to_default')"
                        class="q-mr-sm"
                        @click="openResetAllDialog(key, item)"
                      />
                      <f-btn
                        icon="add"
                        :label="$t('new')"
                        @click="goToAddNew(key)"
                      />
                    </div>
                    <div
                      class="row q-px-md q-py-sm text-weight-bold items-center xslt-header-row back-white"
                      style="border-bottom: 2px solid #e0e0e0"
                    >
                      <div style="width: 22%">
                        <q-icon name="article" size="16px" class="q-mr-xs" />
                        {{ $t('name') }}
                      </div>
                      <div style="width: 13%" class="text-center">
                        {{ $t('status') }}
                      </div>
                      <div style="width: 18%">{{ $t('type') }}</div>
                      <div style="width: 22%">{{ $t('version') }}</div>
                      <div style="width: 22%">
                        <q-icon name="update" size="16px" class="q-mr-xs" />
                        {{ $t('last_modified_at') }}
                      </div>
                    </div>
                    <q-tree
                      :nodes="customDocEDI(item)"
                      node-key="label"
                      default-expand-all
                      :expanded="expandedKeys"
                    >
                      <template v-slot:default-header="prop">
                        <div
                          class="focus"
                          style="
                            width: 100%;
                            border: 1.5px solid #efefef !important;
                          "
                        >
                          <q-markup-table flat>
                            <tbody>
                              <tr
                                class="cursor-pointer xslt-row"
                                @click="rowCliked(prop.node.data, key)"
                              >
                                <td class="q-td text-left" style="width: 22%">
                                  {{
                                    modifiedString(
                                      prop.node.data?.attribute_name,
                                    )
                                  }}
                                </td>
                                <td class="q-td text-center" style="width: 13%">
                                  <q-badge
                                    v-if="isDefaultAttribute(prop.node.data)"
                                    label="Default"
                                    color="orange"
                                    text-color="white"
                                    size="sm"
                                  />
                                  <q-badge
                                    v-else
                                    label="Custom"
                                    color="positive"
                                    text-color="white"
                                    size="sm"
                                  />
                                </td>
                                <td class="q-td text-left" style="width: 18%">
                                  <q-badge
                                    :label="prop.node.data?.attribute_type"
                                    :color="
                                      getTypeColor(
                                        prop.node.data?.attribute_type,
                                      )
                                    "
                                    text-color="white"
                                    class="q-px-sm"
                                  />
                                </td>
                                <td class="q-td text-left" style="width: 22%">
                                  <q-badge
                                    v-if="
                                      prop.node.data?.version &&
                                      prop.node.data?.version !== 'null'
                                    "
                                    :label="'v' + prop.node.data?.version"
                                    color="grey-6"
                                    text-color="white"
                                    class="q-px-sm"
                                  />
                                  <span v-else class="text-grey-5">—</span>
                                </td>
                                <td class="q-td text-left" style="width: 22%">
                                  <q-icon
                                    name="schedule"
                                    size="14px"
                                    class="q-mr-xs"
                                  />
                                  {{
                                    prop.node.data?.last_modified_on
                                      ? formatDateAccordingToPreference(
                                          prop.node.data?.last_modified_on,
                                        )
                                      : formatDateAccordingToPreference(
                                          prop.node.data?.created_on,
                                        )
                                  }}
                                </td>
                                <td class="q-td text-right">
                                  <q-btn
                                    flat
                                    dense
                                    round
                                    @click.stop.prevent
                                    icon="more_vert"
                                    class="action-menu-btn"
                                  >
                                    <q-tooltip :delay="500">{{
                                      $t('actions')
                                    }}</q-tooltip>
                                    <q-menu
                                      auto-close
                                      transition-show="jump-down"
                                      transition-hide="jump-up"
                                      anchor="bottom middle"
                                      self="top middle"
                                    >
                                      <q-list dense style="min-width: 100px">
                                        <q-item
                                          clickable
                                          @click="
                                            openDeleteDialog(prop.node.data?.id)
                                          "
                                          v-if="is_admin == true"
                                        >
                                          <q-item-section
                                            ><span class="text-red">{{
                                              $t('delete')
                                            }}</span></q-item-section
                                          >
                                        </q-item>
                                        <q-item
                                          clickable
                                          v-if="
                                            !isDefaultAttribute(prop.node.data)
                                          "
                                        >
                                          <q-item-section
                                            @click="
                                              goToEdit(
                                                prop.node.data?.id,
                                                prop.node.data?.doc_type_key,
                                                key,
                                                prop.node.data?.attribute_name,
                                                prop.node.data?.attribute_type,
                                              )
                                            "
                                            ><span>{{
                                              $t('edit')
                                            }}</span></q-item-section
                                          >
                                        </q-item>
                                        <q-item
                                          clickable
                                          v-if="
                                            !isDefaultAttribute(prop.node.data)
                                          "
                                          @click="
                                            openResetDialog(prop.node.data?.id)
                                          "
                                        >
                                          <q-item-section>
                                            <span class="text-orange">{{
                                              $t('reset_to_default')
                                            }}</span>
                                          </q-item-section>
                                        </q-item>
                                        <q-item
                                          clickable
                                          v-if="
                                            isDefaultAttribute(prop.node.data)
                                          "
                                        >
                                          <q-item-section
                                            @click="
                                              customize(
                                                prop.node.data?.id,
                                                prop.node.data?.doc_type_key,
                                                key,
                                                prop.node.data?.attribute_name,
                                                prop.node.data?.attribute_type,
                                              )
                                            "
                                            ><span>{{
                                              $t('customize')
                                            }}</span></q-item-section
                                          >
                                        </q-item>
                                      </q-list>
                                    </q-menu>
                                  </q-btn>
                                </td>
                              </tr>
                            </tbody>
                          </q-markup-table>
                        </div>
                      </template>
                    </q-tree>
                  </div>
                </div>
              </q-card>
            </q-expansion-item>
            <q-separator />
          </div>
        </template>
      </q-list>
    </div>
  </div>
  <q-dialog v-model="confirmDeleteDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteAttribute()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- Reset to Default Dialog (single attribute) -->
  <q-dialog v-model="confirmResetDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="restart_alt" color="warning" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('reset_to_default_confirm') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          color="warning"
          :label="$t('reset_to_default')"
          v-close-popup
          @click="resetToDefault()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- Reset All to Default Dialog -->
  <q-dialog v-model="confirmResetAllDialog" persistent>
    <q-card style="min-width: 400px">
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="restart_alt" color="warning" text-color="white" />
      </q-card-section>
      <q-card-section>
        <div class="text-h6 text-center q-mb-md">
          {{ $t('reset_all_to_default') }}
        </div>
        <div class="text-body2 q-mb-md">
          {{ $t('reset_all_confirm', { type: resetAllEDocType }) }}
        </div>
        <div class="q-pl-md">
          <div v-for="item in resetAllItems" :key="item.id" class="q-mb-xs">
            • {{ modifiedString(item.attribute_name) }}
          </div>
        </div>
      </q-card-section>
      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          color="warning"
          :label="$t('reset_all')"
          @click="resetAllToDefault()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <q-inner-loading :showing="processing" style="z-index: 1000000000">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions';
import { isAdmin } from 'src/utils/UserDetails';
import { useDocXsltStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import helperUtil from 'src/utils/helperUtil';
import { dynamicObj } from 'src/pages/asn_shipment/store';
import { getCountryFlag } from 'src/utils/edoc-format-utils';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { LocalStorage } from 'quasar';
import { getUserBasedKey } from 'src/utils/cacheHelper';
import { DEFAULT_ORG_UUID, edocFormatFilterStorageKey } from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil, dateUtils],
  components: {},
  mounted() {
    this.restorePersistedFilter();
    this.initView();
    this.is_admin = isAdmin();
    const title = this.$route.query.title?.toString();
    if (title) {
      this.title = title;
    } else {
      this.title = this.params.doc_type;
    }
  },
  watch: {
    e_doc_data: {
      handler(val) {
        const tab = this.$route.query.tab?.toString();
        if (!tab) return;
        if (!val || Object.keys(val).length === 0) return;
        this.$nextTick(() => {
          const el = document.querySelector<HTMLElement>(
            `[data-edoc-format="${tab.toUpperCase()}"]`,
          );
          if (el) this.scrollInToViewStart(el);
        });
      },
      immediate: true,
    },
  },
  data() {
    return {
      title: '',
      searchQuery: '',
      confirmResetDialog: false,
      confirmResetAllDialog: false,
      resetAllEDocType: '',
      resetAllItems: [] as any[],
    };
  },
  computed: {
    filteredEDocData(): Record<string, any[]> {
      if (!this.searchQuery) return this.e_doc_data;
      const filtered: Record<string, any[]> = {};
      for (const [key, items] of Object.entries(this.e_doc_data)) {
        if (key.toLowerCase().includes(this.searchQuery)) {
          filtered[key] = items as any[];
        }
      }
      return filtered;
    },
  },
  methods: {
    edocFilterStorageKey(): string {
      const docType = this.$route.params.doc_type?.toString() ?? '';
      return getUserBasedKey(edocFormatFilterStorageKey + docType);
    },
    onSearchFilter(val: string | null) {
      this.searchQuery = (val ?? '').toLowerCase();
      LocalStorage.set(this.edocFilterStorageKey(), this.searchQuery);
    },
    restorePersistedFilter() {
      const saved = LocalStorage.getItem<string>(this.edocFilterStorageKey());
      if (saved !== null) {
        this.searchQuery = saved;
      }
    },
    getTypeColor(type: string): string {
      const colors: Record<string, string> = {
        XSLT: 'blue',
        JSON: 'purple',
        XML: 'orange',
      };
      return colors[type] || 'grey';
    },
    getFormatTooltip(format: string): string {
      const tooltips: Record<string, string> = {
        // Europe
        FATTURAPA: 'Italian electronic invoicing standard (SDI)',
        'E-SLOG 1.6': 'Slovenian e-invoice standard v1.6',
        'E-SLOG 2.0': 'Slovenian e-invoice standard v2.0',
        EDI: 'Electronic Data Interchange - traditional B2B format',
        FACTURX:
          'French/German hybrid PDF/XML invoice format (ZUGFeRD compatible)',
        'ZUGFERD 1.0': 'German e-invoice standard v1.0',
        'FACTURX 1.0.05 - ZUGFERD 2.1':
          'Combined French/German e-invoice format',
        'FACTURX 1.07.2 - ZUGFERD 2.3': 'Latest French/German e-invoice format',
        PEPPOL: 'Pan-European e-invoicing network standard',
        INVOIC02: 'EDIFACT invoice message type',
        XRECHNUNG: 'German government e-invoicing standard',
        'XRECHNUNG 1.2': 'German e-invoice v1.2',
        'XRECHNUNG 2.1': 'German e-invoice v2.1',
        'XRECHNUNG 3.0': 'German e-invoice v3.0 (latest)',
        TEAPPSXML: 'Finnish e-invoice standard (Tieto)',
        FINVOICE: 'Finnish banking e-invoice standard',
        KSEF: 'Polish National e-Invoice System (KSeF)',
        FACTURAE: 'Spanish electronic invoice format',
        EBINTERFACE: 'Austrian e-invoice standard',
        OIOUBL: 'Danish public sector e-invoice format',
        EHF: 'Norwegian e-Handelsformat',
        'SI-UBL': 'Dutch SimplerInvoicing UBL format',
        SVEFAKTURA: 'Swedish e-invoice format',
        // Asia Pacific
        INVOICENOW: 'Singapore InvoiceNow (PEPPOL-based)',
        'JP PINT': 'Japan PEPPOL International standard',
        MYINVOIS: 'Malaysian e-Invoice (LHDN MyInvois)',
        'PINT A-NZ': 'Australia/New Zealand PEPPOL standard',
        // Middle East
        ZATCA: 'Saudi Arabia ZATCA FATOORA e-invoice',
        // Latin America
        'PERU CPE': 'Peru Comprobante de Pago Electrónico (SUNAT)',
        'PERU FACTURA ELECTRONICA': 'Peru electronic invoice (SUNAT)',
        'CPE SUNAT': 'Peru SUNAT electronic payment voucher',
        'BRAZIL NFE': 'Brazilian Nota Fiscal Eletrônica',
        CFDI: 'Mexican Comprobante Fiscal Digital por Internet (SAT)',
        'ARGENTINA FE': 'Argentine Factura Electrónica (AFIP)',
        'CHILE DTE': 'Chilean Documento Tributario Electrónico (SII)',
        'COLOMBIA FE': 'Colombian Factura Electrónica (DIAN)',
      };
      return tooltips[format] || `${format} e-document format`;
    },
    getCountryFlag,
    initView() {
      this.getDocxsltBy();
    },
    async getDocxsltBy() {
      this.processing = true;
      this.params.doc_type = this.$route.params.doc_type.toString();
      await this.getDocXslt();
      setTimeout(() => {
        this.processing = false;
      }, 2000);
    },
    async goToEdit(
      id: string,
      doc_type: string,
      e_document_type: string,
      attribute_name: string,
      attribute_type: string,
    ) {
      await this.$router.replace({
        query: { ...this.$route.query, tab: e_document_type },
      });
      this.$router.push(
        `/settings/manage-xslt/${doc_type}/${id}/${e_document_type}?attribute_name=${this.modifiedString(attribute_name)}&attribute_type=${attribute_type}&title=${this.title}`,
      );
    },
    async goToAddNew(e_document_type: string) {
      await this.$router.replace({
        query: { ...this.$route.query, tab: e_document_type },
      });
      const doc_type = this.$route.params.doc_type.toString();
      this.$router.push(
        `/settings/record-xslt/${doc_type}/${e_document_type}?title=${this.title}`,
      );
      this.resetCurrentModel();
    },
    modifiedString(val: string) {
      return val ? val.replace(/_/g, ' ') : val;
    },
    openDeleteDialog(attribute_id: string) {
      this.current_model.attribute_id = attribute_id;
      this.confirmDeleteDialog = true;
    },
    isDefaultAttribute(item: any): boolean {
      if (!item?.org_id) return true;
      return item.org_id.toLowerCase() === DEFAULT_ORG_UUID.toLowerCase();
    },
    isCustomAttribute(item: any): boolean {
      return !this.isDefaultAttribute(item) && !!item?.version;
    },
    hasCustomAttributes(items: any[]): boolean {
      return items.some((item) => this.isCustomAttribute(item));
    },
    openResetAllDialog(eDocType: string, items: any[]) {
      this.resetAllEDocType = eDocType;
      this.resetAllItems = items.filter((item) => this.isCustomAttribute(item));
      this.confirmResetAllDialog = true;
    },
    async resetAllToDefault() {
      try {
        this.processing = true;
        for (const item of this.resetAllItems) {
          this.current_model.attribute_id = item.id;
          await this.deleteExtractionAttribute();
        }
        notify.success(this.$t('reset_all_success'));
        this.initView();
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      } finally {
        this.processing = false;
        this.confirmResetAllDialog = false;
      }
    },
    openResetDialog(attribute_id: string) {
      this.current_model.attribute_id = attribute_id;
      this.confirmResetDialog = true;
    },
    async resetToDefault() {
      try {
        this.processing = true;
        await this.deleteExtractionAttribute();
        notify.success(this.$t('reset_to_default_success'));
        this.initView();
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      } finally {
        this.processing = false;
      }
    },
    async deleteAttribute() {
      try {
        await this.deleteExtractionAttribute();
        this.initView();
        notify.success('Attribute deleted successfully');
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      }
    },
    async customize(
      id: string,
      doc_type: string,
      e_document_type: string,
      attribute_name: string,
      attribute_type: string,
    ) {
      ((this.current_model.attribute_name = attribute_name),
        (this.current_model.attribute_type = attribute_type),
        (this.current_model.doc_type_key = doc_type),
        (this.current_model.e_doc_type = e_document_type),
        (this.current_model.doc_type = doc_type));
      await this.listVersion(id);
      this.current_model.xslt_data = this.versions[0].value;
      const response = await this.createExtractionAttribute();
      this.goToEdit(
        response.data.id,
        doc_type,
        e_document_type,
        attribute_name,
        attribute_type,
      );
    },
    buildTree(arr: any[], level = 0): any {
      if (arr.length === 0) return [];
      const tree: dynamicObj = {
        label: `Label ${level + 1}`,
        data: arr[0],
        index: level,
      };
      if (arr.length > 1) {
        tree['children'] = [this.buildTree(arr.slice(1), level + 1)];
      }
      return tree;
    },
    customDocEDI(item: any): any[] {
      const tree = [this.buildTree(item)];
      return tree;
    },
    rowCliked(row: any, key: string) {
      // Removed customization check to allow navigation to edit page for both default and custom attributes
      this.goToEdit(
        row.id,
        row.doc_type_key,
        key,
        row.attribute_name,
        row.attribute_type,
      );
    },
  },
  setup() {
    const doc_xslt = useDocXsltStore();
    const { datePattern } = useSettingStore();
    const {
      getDocXslt,
      resetCurrentModel,
      deleteExtractionAttribute,
      createExtractionAttribute,
      listVersion,
    } = doc_xslt;
    const {
      processing,
      params,
      versions,
      e_doc_data,
      current_model,
      confirmDeleteDialog,
    } = storeToRefs(doc_xslt);
    return {
      expandedKeys: ['Label 1', 'Label 2', 'Label 3'],
      is_admin: ref(false),
      params,
      versions,
      processing,
      e_doc_data,
      current_model,
      confirmDeleteDialog,
      deleteExtractionAttribute,
      createExtractionAttribute,
      resetCurrentModel,
      datePattern,
      listVersion,
      getDocXslt,
    };
  },
});
</script>
